(function () {
    var styleEl = null;
    function addStyle() {
        if (styleEl) return;
        styleEl = document.createElement('style');
        styleEl.setAttribute('data-splitting', 'true');
        styleEl.textContent = '.splitting .char,.splitting .word{display:inline-block}.splitting .word{white-space:nowrap}.splitting br{display:block}';
        document.head.appendChild(styleEl);
    }

    function splitTextNode(node) {
        var text = node.textContent || '';
        if (!text.trim()) return null;

        var fragment = document.createDocumentFragment();
        var words = text.split(/\s+/);

        words.forEach(function (word, wordIndex) {
            var wordSpan = document.createElement('span');
            wordSpan.className = 'word';
            wordSpan.setAttribute('data-word', word);

            var chars = Array.from(word);
            chars.forEach(function (char, charIndex) {
                var charSpan = document.createElement('span');
                charSpan.className = 'char';
                charSpan.style.setProperty('--char-index', charIndex);
                charSpan.textContent = char;
                wordSpan.appendChild(charSpan);
            });

            if (wordIndex < words.length - 1) {
                wordSpan.appendChild(document.createTextNode(' '));
            }

            fragment.appendChild(wordSpan);
        });

        return fragment;
    }

    function appendNode(fragment, node) {
        if (!node) return;

        if (node.nodeType === 3) {
            var textFragment = splitTextNode(node);
            if (textFragment) {
                fragment.appendChild(textFragment);
            }
            return;
        }

        if (node.nodeType === 1 && node.tagName === 'BR') {
            fragment.appendChild(document.createElement('br'));
            return;
        }

        if (node.nodeType === 1) {
            var children = Array.prototype.slice.call(node.childNodes);
            children.forEach(function (child) {
                appendNode(fragment, child);
            });
        }
    }

    function splitElement(el) {
        if (!el || el.dataset.splittingDone === 'true') return;
        addStyle();

        var fragment = document.createDocumentFragment();
        var children = Array.prototype.slice.call(el.childNodes);

        if (!children.length) {
            el.dataset.splittingDone = 'true';
            return;
        }

        children.forEach(function (child) {
            appendNode(fragment, child);
        });

        el.textContent = '';
        el.appendChild(fragment);
        el.dataset.splittingDone = 'true';
    }

    function splitAll() {
        document.querySelectorAll('[data-splitting]').forEach(function (el) {
            splitElement(el);
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', splitAll);
    } else {
        splitAll();
    }
})();
